    def tilingRectangle(self, n: int, m: int) -> int:
      # try brute force backtracking?
      board = [[0 for _ in range(n)] for _ in range(m)]

      ans = math.inf
      def bt(counts):
        nonlocal ans
        if counts >= ans:
          return

        pos = None
        found = False
        for row in range(m):
          for col in range(n):
            if board[row][col] == 0:
              pos = (row, col)
              found = True
              break
          if found:
            break
        if not found:
          ans = min(ans, counts)
          return

        # see how many difference size of squares we can place from this spot
        r, c = pos
        offset = 0
        while r + offset < m and c + offset < n and board[r + offset][c] == 0 and board[r][c + offset] == 0:
          offset += 1
        # max can place size is offset
        for row in range(r, r + offset):
          for col in range(c, c + offset):
            board[row][col] = 1
        # do bt and shrink
        while offset > 0:
          bt(counts + 1)
          # shrink
          for row in range(r, r + offset):
            board[row][c + offset - 1] = 0
          for col in range(c, c + offset):
            board[r + offset - 1][col] = 0
          offset -= 1

      bt(0)
      return ans

class Solution:
    def tilingRectangle(self, n: int, m: int) -> int:
        def find_next(board):
            for i in range(len(board)):
                for j in range(len(board[0])):
                    if not board[i][j]:
                        return i, j
            return -1, -1

        def find_max_length(board, i, j):
            max_length = 1
            while i+max_length-1 < len(board) and \
                  j+max_length-1 < len(board[0]):
                for r in range(i, i+max_length-1):
                    if board[r][j+max_length-1]:
                        return max_length-1
                for c in range(j, j+max_length):
                    if board[i+max_length-1][c]:
                        return max_length-1
                max_length += 1
            return max_length-1

        def fill(board, i, j, length, val):
            for r in range(i, i+length):
                for c in range(j, j+length):
                    board[r][c] = val

        def backtracking(board, count, result):
            if count >= result[0]:  # pruning
                return
            i, j = find_next(board)
            if (i, j) == (-1, -1):  # finished
                result[0] = min(result[0], count)
                return
            max_length = find_max_length(board, i, j)
            for k in reversed(range(1, max_length+1)):
                fill(board, i, j, k, 1)
                backtracking(board, count+1, result)
                fill(board, i, j, k, 0)

        if m > n:
            return self.tilingRectangle(m, n)
        board = [[0]*m for _ in range(n)]
        result = [float("inf")]
        backtracking(board, 0, result)
        return result[0]

class Solution:
    def minimumSwap(self, s1: str, s2: str) -> int:
        h = defaultdict(int)
        count = 0    # variable to keep track of the number of mismatches; it is impossible to make strings equal if count is odd
        for i in range(len(s1)):
            if s1[i] != s2[i]:
                count += 1
                h[s1[i]] += 1
        if count % 2 != 0:     
            return -1
        res, a, b = 0, h['x'], h['y']
        res += a // 2 + b // 2
        if a % 2 == 0:
            return res
        return res + 2

class Solution:
    def minimumSwap(self, s1: str, s2: str) -> int:
        x1, y1 = 0, 0
        for i in range(len(s1)):
            if s1[i] == s2[i]:
                continue
            x1 += int(s1[i] == 'x')
            y1 += int(s1[i] == 'y')
        if x1%2 !=  y1%2:  # impossible
            return -1
        # case1: per xx or yy needs one swap, (x1//2 + y1//2) 
        # case2: per xy or yx needs two swaps, (x1%2 + y1%2)
        return (x1//2 + y1//2) + (x1%2 + y1%2)

